/* Phase 318: attach five exact Sony BRAVIA 3 transparent images. */
add_action('init',function(){
if(get_option('bhc_catalog_image_sony_bravia3_v318'))return;
@ini_set('memory_limit','768M');$map=['K-43S30'=>'sony-k43s30-v318-source.png','K-55S30'=>'sony-k55s30-v318-source.png','K-65S30'=>'sony-k65s30-v318-source.png','K-75S30'=>'sony-k75s30-v318-source.png','K-85S30'=>'sony-k85s30-v318-source.png'];$result=[];
foreach($map as $model=>$srcname){$ids=get_posts(['post_type'=>'product','post_status'=>'any','posts_per_page'=>1,'fields'=>'ids','meta_key'=>'_bhc_model','meta_value'=>$model]);$id=$ids?(int)$ids[0]:0;$src=__DIR__.'/'.$srcname;$rel='bhc-image-references/sony-'.sanitize_title($model).'-v318-4k.png';$file=ABSPATH.'wp-content/uploads/'.$rel;$ok=false;$aid=0;if($id&&is_readable($src)){$im=@imagecreatefrompng($src);if($im){wp_mkdir_p(dirname($file));$w=imagesx($im);$h=imagesy($im);$scale=4096/max($w,$h);$nw=max(1,(int)round($w*$scale));$nh=max(1,(int)round($h*$scale));$c=imagecreatetruecolor($nw,$nh);imagealphablending($c,false);imagesavealpha($c,true);$z=imagecolorallocatealpha($c,0,0,0,127);imagefill($c,0,0,$z);imagecopyresampled($c,$im,0,0,0,0,$nw,$nh,$w,$h);imagepng($c,$file,6);imagedestroy($c);imagedestroy($im);$ok=is_readable($file);}}if($ok){$old=get_post_thumbnail_id($id);if($old)wp_delete_attachment($old,true);$aid=wp_insert_attachment(['post_mime_type'=>'image/png','post_title'=>'Sony '.$model.' اختصاصی 4K شفاف','post_status'=>'inherit','post_parent'=>$id],$file,$id);if($aid&&!is_wp_error($aid)){update_post_meta($aid,'_wp_attached_file',$rel);$q=@getimagesize($file);wp_update_attachment_metadata($aid,['width'=>$q[0]??4096,'height'=>$q[1]??4096,'file'=>$rel,'sizes'=>[]]);set_post_thumbnail($id,$aid);update_post_meta($id,'_bhc_image_generation_status','product_specific_generated');update_post_meta($id,'_bhc_image_status','generated_4k_transparent_verified');update_post_meta($id,'_bhc_image_long_edge',max((int)($q[0]??0),(int)($q[1]??0)));update_post_meta($id,'_bhc_image_featured_verified','yes');}}$result[$model]=['id'=>$id,'ok'=>$ok,'attachment'=>$aid,'exists'=>is_readable($file)];}
